import{_ as t,c as a,o as r,a3 as s}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"REST API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"master/api-reference/index.md","filePath":"master/api-reference/index.md","lastUpdated":1792999845000}'),i={name:"master/api-reference/index.md"};function n(o,e,d,l,c,p){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="rest-api-reference" tabindex="-1">REST API Reference <a class="header-anchor" href="#rest-api-reference" aria-label="Permalink to &quot;REST API Reference&quot;">​</a></h1><p>AureusERP exposes a full-featured REST API that gives you programmatic access to every module in the platform. Whether you are building third-party integrations, automating internal workflows, or syncing data with external systems, the API covers the complete lifecycle of your ERP data — from partners and inventory to products, sales, accounts, and beyond.</p><p>The API is documented and served interactively by <a href="https://scribe.knuckles.wtf/" target="_blank" rel="noreferrer">Scribe</a>. The pages in this section mirror that documentation as static reference — every endpoint is shown as a ready-to-copy <strong>cURL request</strong> with its real <strong>JSON response</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Interactive API Explorer</p><p>A live request builder is also available at your AureusERP installation&#39;s <code>/api/docs</code> endpoint. Use it to fire real requests against your own instance.</p></div><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>All API endpoints are relative to your installation&#39;s base URL:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://{your-domain}/admin/api/v1</span></span></code></pre></div><p>Replace <code>{your-domain}</code> with the domain where AureusERP is installed (e.g., <code>erp.example.com</code>). Throughout the endpoint pages the placeholder host <code>https://your-domain.com</code> is used.</p><h2 id="api-versioning" tabindex="-1">API Versioning <a class="header-anchor" href="#api-versioning" aria-label="Permalink to &quot;API Versioning&quot;">​</a></h2><p>The current API version is <strong>v1</strong>. The version is included in every endpoint path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/admin/api/v1/{resource}</span></span></code></pre></div><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><ol><li><a href="/master/api-reference/authentication.html">Authenticate</a> to obtain a Bearer token.</li><li>Read <a href="/master/api-reference/making-requests.html">Making Requests</a> for the request/response envelope, pagination, filtering, sorting, and relationship includes.</li><li>Review <a href="/master/api-reference/errors.html">Errors &amp; Status Codes</a> to handle failures.</li><li>Browse the <strong>Endpoints</strong> section for every available resource.</li></ol><h2 id="available-resources" tabindex="-1">Available Resources <a class="header-anchor" href="#available-resources" aria-label="Permalink to &quot;Available Resources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Covers</th></tr></thead><tbody><tr><td><a href="/master/api-reference/endpoints/security/authentication.html">Security &amp; Authentication</a></td><td>Login, logout, token management</td></tr><tr><td><a href="/master/api-reference/endpoints/support/currencies.html">Support</a></td><td>Currencies, currency rates, banks, countries, states, units of measure</td></tr><tr><td><a href="/master/api-reference/endpoints/partners/partners.html">Partners</a></td><td>Partners, addresses, bank accounts, titles, tags, industries</td></tr><tr><td><a href="/master/api-reference/endpoints/products/products.html">Products</a></td><td>Products, variants, categories, attributes, packaging, price lists</td></tr><tr><td><a href="/master/api-reference/endpoints/inventory/receipts.html">Inventory</a></td><td>Warehouses, locations, routes, receipts, deliveries, transfers, lots, packages</td></tr><tr><td><a href="/master/api-reference/endpoints/sales/orders.html">Sales</a></td><td>Sales orders, order lines, deliveries, invoices, tags</td></tr><tr><td><a href="/master/api-reference/endpoints/accounts/invoices.html">Accounts</a></td><td>Invoices, bills, credit notes, taxes, journals, payment terms, customers, vendors</td></tr></tbody></table>',15)]))}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
